  <script>
    const carousel = document.getElementById('trendingCarousel');
    document.querySelector('.next').addEventListener('click', () => carousel.scrollBy({ left: carousel.clientWidth * 0.75, behavior: 'smooth' }));
    document.querySelector('.prev').addEventListener('click', () => carousel.scrollBy({ left: -carousel.clientWidth * 0.75, behavior: 'smooth' }));

    const items = [...document.querySelectorAll('.faq-item')];
    items.forEach(item => {
      item.querySelector('.faq-q').addEventListener('click', () => {
        items.forEach(other => {
          const expanded = other === item && !other.classList.contains('active');
          other.classList.toggle('active', expanded);
          other.querySelector('.faq-q').setAttribute('aria-expanded', expanded ? 'true' : 'false');
        });
      });
    });

    document.querySelectorAll('form').forEach(form => {
      form.addEventListener('submit', (event) => {
        event.preventDefault();
        const input = form.querySelector('input[type="email"]');
        if (input && input.checkValidity()) {
          alert('Great! We\'ll use ' + input.value + ' to get you started.');
          form.reset();
        } else if (input) {
          input.reportValidity();
        }
      });
    });
  </script>
</body>
</html>
