        <input id="email" name="email" required autocomplete="username" />
        <label for="password">Password</label>
        <input id="password" type="password" name="password" required autocomplete="current-password" minlength="6" />
        <button type="submit">Continue</button>
      </form>
      <button class="help-toggle" id="helpToggle" type="button" aria-expanded="false">Get help</button>
      <div class="help-content" id="helpContent">
